import pprint


class CheckReport(object):

    def __init__(self):
        self.status = True
        self.data = {}
        self.error_data = {}

    def __bool__(self):
        return self.status

    # Python 2to3 compatibility , __bool__ in python3 , __nonzero__ in python2
    __nonzero__ = __bool__

    def __str__(self):
        return pprint.pformat(self.error_data)

    def __repr__(self):
        return str(self)

    def add_error(self, container, check_name, parameter_name, additional_check_info):
        """
        Method that includes error related information into CheckReport.
        Automatically changes CheckReport.status to False.

        :param str container: Name of the section to which you want to add data ie. managed obj. name
        :param str check_name: Short name for the check.
        :param str parameter_name: Parameter name.
        :param str additional_check_info: Additional check information.
        :return:
        """
        self.status = False
        if container not in self.error_data:
            self.error_data[container] = {}

        if check_name not in self.error_data[container]:
            self.error_data[container][check_name] = {}

        check_error_data = {parameter_name: additional_check_info}
        self.error_data[container][check_name].update(check_error_data)
